const items = [
  { icon: "⚡", title: "Fast Setup", text: "No bundler. No config. No headache." },
  { icon: "🎨", title: "Modern UI", text: "Clean dark theme for landing pages." },
  { icon: "🧩", title: "Components", text: "Reusable React components." },
  { icon: "🚀", title: "Upgradable", text: "Migrate to Vite or Next.js anytime." }
];

export default function Features() {
  return (
    <section className="features" id="features">
      <div className="features-header">
        <h2>Features</h2>
        <p>A simple structure you can grow into a website.</p>
      </div>

      <div className="features-grid">
        {items.map((item) => (
          <article className="feature-card" key={item.title}>
            <div className="feature-icon">{item.icon}</div>
            <h3 className="feature-title">{item.title}</h3>
            <p className="feature-text">{item.text}</p>
          </article>
        ))}
      </div>
    </section>
  );
}
